#!/usr/bin/env bash
#
# 관리형 PostgreSQL(Neon · Supabase · Aiven …)을 이 저장소가 쓸 수 있는 상태로 만든다.
# 그리고 그 전에 **정말 쓸 수 있는지부터 확인한다.**
#
# ── 왜 확인이 먼저인가 ─────────────────────────────────────────────────
#
# "무료 PostgreSQL" 이라고 소개되는 것 중에 PostgreSQL 이 아닌 것이 있다.
# OCI 무료 티어의 HeatWave 는 MySQL 이고 Autonomous Database 는 Oracle DB 다.
# 둘 다 이 저장소에서는 쓸 수 없다 — 코드가 PostgreSQL 고유 기능에 의존한다:
#
#   · FOR UPDATE SKIP LOCKED            아웃박스·메일·SMS 디스패처가 전부 이걸로 행을 집는다
#   · jsonb                             이벤트 페이로드 저장
#   · PARTITION BY RANGE                아웃박스 테이블 파티셔닝(docs/12)
#   · GENERATED BY DEFAULT AS IDENTITY  마이그레이션 22곳
#
# 그래서 이 스크립트는 provision 전에 위 네 가지를 **실제로 실행해 본다**. 문법만 보는 것이
# 아니라 임시 테이블을 만들어 돌린다. 되면 provision, 안 되면 무엇이 안 되는지 알려주고 멈춘다.
#
# ── 사용 ───────────────────────────────────────────────────────────────
#
#   # 관리자 URL 로 붙는다(provider 콘솔이 주는 것). 비밀번호는 인자로 주지 말고 환경변수로.
#   export ADMIN_URL='postgresql://owner@ep-xxx.aws.neon.tech/neondb?sslmode=require'
#   export PGPASSWORD='...'
#
#   ops/25-provision-external-postgres.sh --check              # 진단만
#   ops/25-provision-external-postgres.sh                      # 진단 + 생성
#                                                              (product 비밀번호는 물어본다)
#
# ⚠️ --app-password 로도 줄 수 있지만 쉘 히스토리에 남는다. 그냥 물어보게 두는 편이 낫다.
#
# ⚠️ 비밀번호가 **둘** 나온다. 헷갈리기 쉬우니 구분할 것:
#     PGPASSWORD      = ADMIN_URL 의 관리자 비밀번호. 프로비저닝하는 동안만 쓴다
#     APP_DB_PASSWORD = 애플리케이션 역할(product)에 **새로 설정할** 비밀번호.
#                       이 값이 k8s/20-secret.yaml 의 LOCAL_DB_PASSWORD 가 된다
#
set -euo pipefail

ADMIN_URL="${ADMIN_URL:-}"
APP_ROLE="${APP_ROLE:-product}"
APP_DB_PASSWORD="${APP_DB_PASSWORD:-}"
CHECK_ONLY=0

# 각 서비스 Deployment 의 JDBC URL 이 가리키는 이름들. 하나라도 빠지면 그 서비스는
# Flyway 마이그레이션 단계에서 'database "xxx" does not exist' 로 기동에 실패한다.
DATABASES=(userdb productdb metadb cartdb orderdb paydb coupondb chatdb notificationdb deliverydb)

log()  { printf '\n\033[1;36m▶ %s\033[0m\n' "$*"; }
info() { printf '  \033[0;32m✓\033[0m %s\n' "$*"; }
warn() { printf '  \033[0;33m!\033[0m %s\n' "$*"; }
fail() { printf '  \033[0;31m✗\033[0m %s\n' "$*"; }
die()  { printf '\n\033[0;31m✗ %s\033[0m\n' "$*" >&2; exit 1; }

# 이 비밀번호는 **서로 다른 이스케이프 규칙 넷**을 통과한다. 하나만 어긋나도 결과는
# 똑같이 `password authentication failed` 라, 어디서 틀렸는지 메시지가 알려 주지 않는다:
#
#   ① provider 콘솔의 접속 URI   퍼센트 인코딩 (`@` → `%40`)  ← 이걸 그대로 복사하면 틀린다
#   ② k8s/20-secret.yaml         YAML 인용
#   ③ kubectl patch -p '{...}'   JSON 이스케이프
#   ④ JDBC 로 실제 전달          **원본 그대로**
#
# 그래서 영숫자만 쓰면 넷이 전부 같은 문자열이 된다. 강제하지는 않되 알리고 넘어간다.
# (엔트로피는 길이로 확보한다 — 24자 영숫자면 특수문자 섞인 12자보다 강하다.)
warn_special_chars() {
    # ⚠️ 둥근따옴표·대시는 **거의 항상 복사 사고**다. 웹이나 문서에서 값을 옮길 때
    #    편집기가 ' 를 ‘ ’ 로, - 를 – 로 바꿔 놓는다. 그리고 `read -rs` 는 화면에
    #    아무것도 보여 주지 않으므로 눈으로 잡을 수 없고, 길이 검사도 통과한다
    #    (따옴표가 붙어 두 자 늘어났을 뿐이다).
    #
    #    실제로 이 저장소는 같은 문자에 두 번 당했다. 한 번은 ADMIN_URL(§2 의
    #    `invalid connection option`), 한 번은 이 비밀번호 — 콘솔의 URI 에
    #    `%E2%80%98…%E2%80%99` 로 인코딩되어 나타나서야 정체가 드러났다.
    #
    #    이건 경고가 아니라 거부한다. 의도적으로 쓸 이유가 없고, 통과시키면 YAML·JSON·
    #    셸 중 어딘가에서 반드시 깨지는데 그때의 오류 메시지는 원인을 가리키지 않는다.
    case "$APP_DB_PASSWORD" in
        *‘*|*’*|*“*|*”*|*–*|*—*)
            die "비밀번호에 **둥근따옴표나 긴 대시**가 들어 있습니다 (‘ ’ “ ” – —).

    복사할 때 편집기가 바꿔 넣은 것입니다. 값의 일부가 되어 버렸고, 그대로 두면
    나중에 'password authentication failed' 로만 나타나 원인을 찾기 매우 어렵습니다.

    직접 타이핑하거나, 영숫자로 새로 만드세요:
        openssl rand -hex 16"
            ;;
    esac
    case "$APP_DB_PASSWORD" in
        *[!A-Za-z0-9._~-]*)
            warn "비밀번호에 영숫자·._~- 외의 문자가 있습니다."
            warn "  틀리기 쉬워집니다 — 이 값은 네 곳을 서로 다른 방식으로 통과합니다:"
            warn "    · provider 콘솔 URI 는 **퍼센트 인코딩**해서 보여 줍니다(@ → %40)."
            warn "      거기서 복사한 값을 그대로 넣으면 인증에 실패합니다"
            warn "    · YAML(20-secret.yaml) · JSON(kubectl patch) · 셸 인용도 각각 다릅니다"
            warn "  가능하면 영숫자만 쓰고 **길이로** 강도를 확보하세요:  openssl rand -hex 16"
            ;;
    esac
}

while [ $# -gt 0 ]; do
    case "$1" in
        --admin-url)    ADMIN_URL="$2";       shift 2 ;;
        --app-role)     APP_ROLE="$2";        shift 2 ;;
        --app-password) APP_DB_PASSWORD="$2"; shift 2 ;;
        --check)        CHECK_ONLY=1;         shift ;;
        -h|--help) sed -n '2,40p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *) die "알 수 없는 옵션: $1" ;;
    esac
done

command -v psql >/dev/null || die "psql 이 필요합니다 (postgresql-client)"
[ -n "$ADMIN_URL" ] || die "ADMIN_URL 이 필요합니다 — provider 콘솔의 관리자 접속 문자열"

# ⚠️ URI 로 시작하지 않으면 libpq 는 이걸 **키=값 문자열**로 해석한다. 그러면 오류가
#    'invalid connection option "...sslmode"' 처럼 나와서 진짜 원인(문자열 앞의 쓰레기 문자)이
#    전혀 드러나지 않는다. 실제로 복사 과정에서 곧은따옴표가 둥근따옴표(’ ‘)로 바뀌어
#    값 안에 들어간 적이 있다. 여기서 먼저 잡는다.
case "$ADMIN_URL" in
    postgresql://*|postgres://*) : ;;
    *) die "ADMIN_URL 이 postgresql:// 로 시작하지 않습니다.

    받은 값의 앞부분: $(printf '%.30s' "$ADMIN_URL")…

    붙여넣기 과정에서 따옴표가 둥근따옴표(’ ‘)로 바뀌어 값 안에 섞이는 일이 흔합니다.
    따옴표를 **직접 타이핑해서** 다시 지정하세요:
        export ADMIN_URL=\"postgresql://USER@HOST/DB?sslmode=require\"" ;;
esac

# ⚠️ 풀러(PgBouncer) 엔드포인트로는 프로비저닝을 할 수 없다. transaction 모드가 모든 문장을
#    트랜잭션으로 감싸는데 CREATE DATABASE 는 트랜잭션 블록 안에서 실행할 수 없기 때문이다.
#    애플리케이션 접속에는 풀러를 써도 되지만(그때는 docs/32 §9 의 prepareThreshold 주의),
#    이 스크립트는 직결 주소가 필요하다.
case "$ADMIN_URL" in
    *-pooler.*|*pgbouncer*)
        warn "ADMIN_URL 이 **풀러(pooler) 엔드포인트**로 보입니다."
        warn "  CREATE DATABASE 는 트랜잭션 블록 안에서 실행할 수 없어 3단계에서 실패합니다."
        warn "  호스트에서 '-pooler' 를 빼거나, provider 콘솔에서 connection pooling 을 끈"
        warn "  직결(direct) 주소를 쓰세요." ;;
esac

# -X: ~/.psqlrc 무시 (개인 설정이 출력 형식을 바꿔 파싱을 깨뜨린다)
PSQL=(psql -X -v ON_ERROR_STOP=1 -qAt "$ADMIN_URL")

# ---------------------------------------------------------------- 0. 접속

log "0/4  접속"
SERVER_VERSION=$("${PSQL[@]}" -c "SHOW server_version" 2>/dev/null) \
    || die "접속하지 못했습니다. ADMIN_URL 과 PGPASSWORD 를 확인하세요.
    (Supabase 직결 엔드포인트는 IPv6 전용입니다 — IPv4 만 있는 호스트라면 pooler 주소를 쓰세요.)"
info "PostgreSQL $SERVER_VERSION"

case "${SERVER_VERSION%%.*}" in
    1[4-9]|2[0-9]) : ;;
    *) warn "이 저장소는 PostgreSQL 16 에서 검증했습니다. $SERVER_VERSION 은 미검증입니다." ;;
esac

# ---------------------------------------------------------------- 1. 기능 검증

log "1/4  이 저장소가 요구하는 기능 검증"

FAILED=0

# ⚠️ 실패하면 **서버가 준 메시지를 그대로 보여 준다.** 처음에는 stderr 를 버렸는데,
#    그 결과 "SKIP LOCKED 가 없습니다" 라는 있을 수 없는 진단이 나오고 원인을 볼 방법이
#    없었다. 검사 스크립트가 왜 실패했는지 말해 주지 못하면 검사가 아니라 점괘다.
probe() {  # probe <이름> <설명> <SQL>
    local name="$1" what="$2" sql="$3" err
    if err=$("${PSQL[@]}" -c "$sql" 2>&1 >/dev/null); then
        info "$name — $what"
    else
        fail "$name — $what"
        # psql 은 여러 줄을 뱉는다(ERROR / DETAIL / LINE n:). 첫 두 줄이면 원인이 보인다.
        printf '%s\n' "$err" | head -2 | sed 's/^/      /'
        FAILED=$((FAILED + 1))
    fi
}

# (예전에는 카탈로그 조회 결과를 보는 probe_true 가 따로 있었다. 지웠다 — 카탈로그로
#  권한을 판정하는 방식 자체가 틀렸기 때문이다. 아래 CREATE DATABASE 검사의 주석 참조.)

# ⚠️ 검사는 전부 **전용 스키마 안의 실제 테이블**로 한다. 처음에는 CREATE TEMP TABLE 을
#    썼는데, 관리형 엔드포인트에서 임시 테이블 세 검사만 몰살하고 나머지는 통과하는 결과가
#    나왔다(SKIP LOCKED 와 jsonb 가 "없는" PostgreSQL 16 이라는 불가능한 진단). 임시 테이블은
#    세션에 묶여 있어 풀러·프록시가 끼면 신뢰할 수 없다 — 정작 검사해야 할 것은 **애플리케이션이
#    실제로 쓰는 것**, 즉 영구 테이블이다. public 대신 전용 스키마를 쓰는 이유는 남의 객체와
#    충돌하지 않기 위해서이고, PostgreSQL 15+ 는 public 의 CREATE 권한이 기본으로 없어
#    실패했을 때 "기능이 없다"로 오독되기 때문이기도 하다.
PROBE_SCHEMA="probe_ecommerce_msa"
PROBE_DB="probe_ecommerce_msa_db"

# 뒷정리는 어떤 경로로 끝나든 반드시 돈다(검사 실패로 die 해도).
cleanup_probes() {
    "${PSQL[@]}" -c "DROP SCHEMA IF EXISTS $PROBE_SCHEMA CASCADE" >/dev/null 2>&1 || true
    "${PSQL[@]}" -c "DROP DATABASE IF EXISTS \"$PROBE_DB\"" >/dev/null 2>&1 || true
}
trap cleanup_probes EXIT

# 이전 실행이 중간에 죽어 스키마가 남아 있을 수 있다. 지울 수 있으면 지우고, **남의 소유라
# 지울 수 없으면 이름을 바꿔서 진행한다** — 남은 잔여물 때문에 검사 자체가 시작도 못 하는
# 상황을 만들지 않기 위해서다(실제로 그렇게 막혔다: 'must be owner of schema ...').
if ! "${PSQL[@]}" -c "DROP SCHEMA IF EXISTS $PROBE_SCHEMA CASCADE" >/dev/null 2>&1; then
    LEFTOVER="$PROBE_SCHEMA"
    PROBE_SCHEMA="${PROBE_SCHEMA}_$$"
    warn "이전 실행이 남긴 '$LEFTOVER' 스키마를 지울 수 없습니다(소유자가 다릅니다)."
    warn "  이번 검사는 '$PROBE_SCHEMA' 로 진행합니다. 남은 것은 그 소유자 계정에서 지우세요:"
    warn "    DROP SCHEMA $LEFTOVER CASCADE;"
fi

# 나머지 검사가 전부 이 스키마 안에서 돌기 때문에 이것이 첫 번째여야 한다.
# 여기서 실패하면 뒤의 검사는 전부 "스키마가 없다"로 줄줄이 실패해 진짜 원인을 덮는다.
# 그래서 여기서만은 바로 멈춘다.
probe "스키마·테이블 생성 권한" "Flyway 가 마이그레이션을 적용하려면 필요하다" "
    CREATE SCHEMA $PROBE_SCHEMA;"

if [ "$FAILED" -gt 0 ]; then
    die "이 역할로는 객체를 만들 수 없습니다 — 위 메시지가 원인입니다.

    기능의 문제가 아니라 **권한**의 문제일 가능성이 높습니다. 확인할 것:
      · 관리자(소유자) 역할로 접속했는가 — provider 콘솔의 'owner' 계정
      · 읽기 전용 복제본(read replica) 엔드포인트로 붙지 않았는가
      · PostgreSQL 15+ 는 public 스키마의 CREATE 권한이 기본으로 없다"
fi

probe "SKIP LOCKED" "아웃박스·메일·SMS 디스패처가 행을 집는 방식" "
    CREATE TABLE $PROBE_SCHEMA.skip(id int);
    INSERT INTO $PROBE_SCHEMA.skip VALUES (1);
    SELECT id FROM $PROBE_SCHEMA.skip ORDER BY id FOR UPDATE SKIP LOCKED;"

probe "jsonb" "이벤트 페이로드 컬럼" "
    CREATE TABLE $PROBE_SCHEMA.js(payload jsonb);
    INSERT INTO $PROBE_SCHEMA.js VALUES ('{\"a\":1}'::jsonb);
    SELECT payload->>'a' FROM $PROBE_SCHEMA.js;"

probe "IDENTITY 컬럼" "마이그레이션 22곳이 쓰는 기본키 생성 방식" "
    CREATE TABLE $PROBE_SCHEMA.ident(id bigint GENERATED BY DEFAULT AS IDENTITY);
    INSERT INTO $PROBE_SCHEMA.ident DEFAULT VALUES;"

probe "선언적 파티셔닝" "아웃박스 테이블 RANGE 파티션(docs/12)" "
    CREATE TABLE $PROBE_SCHEMA.part(id bigint, created_at timestamptz NOT NULL)
        PARTITION BY RANGE (created_at);
    CREATE TABLE $PROBE_SCHEMA.part_p0 PARTITION OF $PROBE_SCHEMA.part
        FOR VALUES FROM ('2000-01-01') TO ('2000-02-01');"

# ⚠️ 카탈로그를 읽어 판정하지 않는다. 예전에는 이랬는데
#
#      SELECT 1 FROM pg_roles WHERE rolname = current_user AND (rolcreatedb OR rolsuper)
#
#    이게 통과해 놓고 정작 3/3 단계에서 'permission denied to create database' 로 죽었다.
#    관리형 서비스는 이벤트 트리거나 자체 훅으로 CREATE DATABASE 를 막을 수 있고, 그런 제약은
#    pg_roles 에 나타나지 않는다. **할 수 있는지 알고 싶으면 해 보는 수밖에 없다** —
#    TEMP 테이블 때와 같은 교훈이다. 만들고 바로 지운다.
probe "CREATE DATABASE" "서비스별 데이터베이스 10개를 만들 수 있어야 한다" "
    CREATE DATABASE \"$PROBE_DB\";"
"${PSQL[@]}" -c "DROP DATABASE IF EXISTS \"$PROBE_DB\"" >/dev/null 2>&1 || true

if [ "$FAILED" -gt 0 ]; then
    die "$FAILED 개 항목이 실패했습니다. **위에 찍힌 서버 메시지가 원인입니다** — 먼저 그것부터 읽으세요.

    'ERROR: syntax error' 나 'type jsonb does not exist' 라면 애초에 PostgreSQL 이 아닙니다
    (MySQL 계열 HeatWave, Oracle Autonomous Database 가 여기서 걸립니다).
    'permission denied' 라면 기능이 아니라 권한 문제이므로 접속 계정을 바꾸면 됩니다.

    ⚠️ **CREATE DATABASE 만 실패했다면** 계정 문제가 아닐 수 있습니다. 무료 티어 중에는
       데이터베이스를 하나만 주고 추가 생성을 아예 막는 곳이 있습니다(그런 제약은
       pg_roles 에 나타나지 않아 실행해 봐야만 압니다). 그 경우 선택지는 둘입니다:
         · CREATE DATABASE 를 허용하는 provider 로 옮긴다
         · 데이터베이스 하나에 **서비스별 스키마**로 나눈다 — 각 서비스의 JDBC URL 에
           ?currentSchema=<서비스> 를 붙여야 하므로 Deployment 10곳을 고쳐야 합니다
           (docs/32 §9)"
fi

# 커넥션 한도는 실패가 아니라 경고다 — DB_POOL_SIZE 로 맞출 수 있다.
MAXC=$("${PSQL[@]}" -c "SHOW max_connections" 2>/dev/null || echo "?")
info "max_connections = $MAXC"
if [ "$MAXC" != "?" ] && [ "$MAXC" -lt 100 ] 2>/dev/null; then
    warn "10 데이터소스 × DB_POOL_SIZE × 레플리카 수가 이 값을 넘으면 늦게 뜬 파드가"
    warn "  'FATAL: sorry, too many clients already' 로 기동에 실패합니다."
    warn "  k8s-overlays/external 의 DB_POOL_SIZE 를 낮추거나 pooler 엔드포인트를 쓰세요."
fi

if [ "$CHECK_ONLY" = "1" ]; then
    log "진단만 수행했습니다 (--check). 생성하려면 --check 없이 다시 실행하세요."
    exit 0
fi

# ---------------------------------------------------------------- 2. 역할

log "2/4  애플리케이션 역할: $APP_ROLE"

# 비밀번호가 없으면 **여기서 물어본다.** 예전에는 그냥 die 하고 사용자에게
#   read -rs APP_DB_PASSWORD && export APP_DB_PASSWORD
# 를 직접 치라고 안내했는데, `read -rs` 는 프롬프트도 에코도 없어서 셸이 멈춘 것처럼 보인다.
# 거기서 Enter 를 누르면 **빈 값이 조용히 들어가** 다시 여기로 돌아온다. 셸 문법을 요구하는
# 대신 스크립트가 물어보는 것이 맞다(-p 는 zsh 에서 의미가 다르므로 printf 로 띄운다).
if [ -z "$APP_DB_PASSWORD" ]; then
    if [ -t 0 ]; then
        printf '\n  %s 역할에 설정할 비밀번호 (입력해도 화면에 보이지 않습니다)\n' "$APP_ROLE"
        printf '  ⚠️ 관리자(ADMIN_URL) 비밀번호가 아니라 **애플리케이션용** 새 비밀번호입니다.\n'
        printf '     이 값이 그대로 k8s/20-secret.yaml 의 LOCAL_DB_PASSWORD 가 됩니다.\n\n'
        printf '  비밀번호: '
        read -rs APP_DB_PASSWORD; echo
        printf '  다시 한 번: '
        read -rs CONFIRM_PW; echo
        [ "$APP_DB_PASSWORD" = "$CONFIRM_PW" ] || die "두 번 입력한 값이 다릅니다."
        [ -n "$APP_DB_PASSWORD" ] || die "빈 비밀번호는 쓸 수 없습니다."
        unset CONFIRM_PW
        info "${#APP_DB_PASSWORD}자 비밀번호를 받았습니다"
    else
        die "APP_DB_PASSWORD 가 필요합니다 (또는 --app-password).
    터미널이 아니어서 물어볼 수 없습니다. 환경변수로 넘기세요:
        APP_DB_PASSWORD='...' $0
    이 값은 k8s/20-secret.yaml 의 LOCAL_DB_PASSWORD 와 **같아야** 합니다."
    fi
fi

# 대화형으로 받았든 --app-password·환경변수로 받았든 똑같이 확인한다.
warn_special_chars

# 비밀번호를 SQL 문자열로 넣는다. 작은따옴표는 두 번 써서 이스케이프한다 —
# 그러지 않으면 비밀번호에 ' 가 있을 때 문장이 그 자리에서 끊긴다(그리고 로그에 새어 나간다).
ESCAPED_PW=${APP_DB_PASSWORD//\'/\'\'}

if [ "$("${PSQL[@]}" -c "SELECT 1 FROM pg_roles WHERE rolname = '$APP_ROLE'")" = "1" ]; then
    # ⚠️ 역할이 이미 있으면 CREATEROLE 만으로는 못 바꾼다 — 그 역할에 대한 ADMIN 옵션이 필요하다.
    #    남이(또는 provider 가) 만든 역할일 때 여기서 걸린다.
    if ! ALTER_ERR=$("${PSQL[@]}" -c "ALTER ROLE \"$APP_ROLE\" WITH LOGIN PASSWORD '$ESCAPED_PW'" 2>&1 >/dev/null); then
        die "역할 '$APP_ROLE' 이 이미 있는데 이 계정으로는 바꿀 수 없습니다.
    $ALTER_ERR

    셋 중 하나를 고르세요:
      · provider 콘솔에서 '$APP_ROLE' 의 비밀번호를 직접 설정하고, 그 값을
        APP_DB_PASSWORD 와 k8s/20-secret.yaml 의 LOCAL_DB_PASSWORD 에 넣는다
      · 다른 이름을 쓴다:  --app-role myapp
        (이때 k8s/40~48-*.yaml 의 SPRING_DATASOURCE*_USERNAME 도 같이 바꿔야 합니다)
      · 그 역할을 만든 계정으로 접속한다"
    fi
    info "기존 역할의 비밀번호를 갱신했습니다"
else
    "${PSQL[@]}" -c "CREATE ROLE \"$APP_ROLE\" WITH LOGIN PASSWORD '$ESCAPED_PW'" >/dev/null
    info "역할을 만들었습니다"
fi

# ⚠️ `CREATE DATABASE ... OWNER <역할>` 은 현재 사용자가 그 역할로 **SET ROLE 할 수 있어야**
#    한다. 못 하면 PostgreSQL 16 은 이렇게 거부한다:
#
#      ERROR:  must be able to SET ROLE "product"
#
#    슈퍼유저는 언제나 가능하지만 **관리형 서비스의 관리자 계정은 대개 슈퍼유저가 아니다.**
#    (Neon 의 neondb_owner, Aiven 의 avnadmin 등은 CREATEDB·CREATEROLE 만 가진 일반 역할이다.)
#    역할을 방금 만들었다면 PostgreSQL 16 은 생성자에게 자동으로 멤버십을 주지만, 역할이
#    **이미 있었다면** 그 자동 부여가 없어 여기서 걸린다.
#
#    그래서 멤버십을 명시적으로 받아 본다. 그것도 안 되면 소유권을 포기하고 권한만 준다 —
#    Flyway 에 필요한 것은 public 스키마의 CREATE 권한이지 데이터베이스 소유권이 아니다.
CAN_SET_ROLE=1
if ! "${PSQL[@]}" -c "SET ROLE \"$APP_ROLE\"" >/dev/null 2>&1; then
    if "${PSQL[@]}" -c "GRANT \"$APP_ROLE\" TO CURRENT_USER" >/dev/null 2>&1 \
        && "${PSQL[@]}" -c "SET ROLE \"$APP_ROLE\"" >/dev/null 2>&1; then
        info "$APP_ROLE 멤버십을 현재 사용자에게 부여했습니다 (소유자 지정에 필요)"
    else
        CAN_SET_ROLE=0
        warn "현재 사용자는 $APP_ROLE 로 SET ROLE 할 수 없습니다 — 소유자 지정을 건너뜁니다."
        warn "  데이터베이스는 현재 사용자가 소유하고, $APP_ROLE 에는 권한만 부여합니다."
        warn "  애플리케이션 동작에는 지장이 없습니다(Flyway 는 CREATE 권한만 필요합니다)."
    fi
fi

# ---------------------------------------------------------------- 3. 데이터베이스

log "3/4  데이터베이스 ${#DATABASES[@]}개"

# ADMIN_URL 에서 데이터베이스 이름만 갈아 끼우기 위해 앞뒤를 분리해 둔다.
DB_BASE="${ADMIN_URL%%\?*}"; DB_BASE="${DB_BASE%/*}"
DB_QS=""
case "$ADMIN_URL" in *\?*) DB_QS="?${ADMIN_URL#*\?}" ;; esac

for db in "${DATABASES[@]}"; do
    if [ "$("${PSQL[@]}" -c "SELECT 1 FROM pg_database WHERE datname = '$db'")" = "1" ]; then
        info "$db (이미 있음)"
    else
        # CREATE DATABASE 는 트랜잭션 블록 안에서 실행할 수 없어 psql 호출을 따로 한다.
        if [ "$CAN_SET_ROLE" = "1" ]; then
            "${PSQL[@]}" -c "CREATE DATABASE \"$db\" OWNER \"$APP_ROLE\"" >/dev/null
            info "$db (생성 · 소유자 $APP_ROLE)"
        else
            "${PSQL[@]}" -c "CREATE DATABASE \"$db\"" >/dev/null
            info "$db (생성 · 소유자는 현재 사용자)"
        fi
    fi

    # 권한 두 가지가 **모두** 필요하다. 소유자면 이미 갖고 있어 무해하고, 소유자가 아니라면
    # 이 부여가 유일한 경로다.
    #
    #  ① 데이터베이스의 CREATE   — 마이그레이션이 `CREATE SCHEMA users` 처럼 **자기 스키마를
    #                              만든다**(9개 서비스 전부). 이게 없으면 V1 에서 곧바로
    #                              'permission denied for database <db>' 로 죽는다.
    #                              public 스키마 권한만 줘서는 부족하다 — 실측으로 확인했다.
    #  ② public 스키마의 CREATE  — PostgreSQL 15 부터 기본으로 없다. 없으면
    #                              'permission denied for schema public'.
    if ! GRANT_ERR=$(psql -X -v ON_ERROR_STOP=1 -qAt "${DB_BASE}/${db}${DB_QS}" \
            -c "GRANT CREATE, CONNECT, TEMPORARY ON DATABASE \"$db\" TO \"$APP_ROLE\"" \
            -c "GRANT ALL ON SCHEMA public TO \"$APP_ROLE\"" 2>&1 >/dev/null); then
        if [ "$CAN_SET_ROLE" = "1" ]; then
            warn "  $db: 권한 부여를 건너뛰었습니다 — $APP_ROLE 이 소유자이므로 필요 없습니다"
        else
            die "$db: $APP_ROLE 에 필요한 권한을 주지 못했습니다.
    $GRANT_ERR

    소유자도 아니고 권한도 없으면 Flyway 가 첫 마이그레이션에서 죽습니다.
    관리자(소유자) 계정으로 접속했는지 확인하세요."
        fi
    fi
done

# ---------------------------------------------------------------- 최종 확인
#
# ⚠️ 여기까지는 전부 **관리자 자격증명**으로 한 일이다. 애플리케이션 역할로 실제 로그인이
#    되는지는 아직 아무도 확인하지 않았다 — 그리고 그게 실제로 어긋난 적이 있다.
#
#    비밀번호에 둥근따옴표가 섞여 들어가면 ALTER ROLE 은 **성공한다**(그 문자까지 포함한
#    비밀번호가 설정된다). 그런데 사람은 따옴표 없는 값을 k8s Secret 에 넣는다. 그러면
#    프로비저닝은 초록불인데 배포가 `password authentication failed` 로 막히고, 원인이
#    비밀번호라는 것도 그 메시지로는 드러나지 않는다. 실제로 이 저장소가 그렇게 막혔다.
#
#    설정한 값으로 한 번 붙어 보면 그 자리에서 끝난다.

log "4/4  애플리케이션 역할로 로그인 확인"

# ADMIN_URL 을 정규식으로 고쳐 쓰지 않고 **호스트만 뽑아 새로 조립한다.** 그 편이
# 스킴·자격증명·포트·경로·쿼리의 조합을 하나하나 다루는 것보다 안전하다.
#   postgresql://user:pw@host:5432/db?opts  →  host:5432
APP_HOST=$(printf '%s' "$ADMIN_URL" | sed -E 's#^[a-z]+://##; s#^[^@]*@##; s#[/?].*$##')
APP_URL="postgresql://$APP_ROLE@$APP_HOST/${DATABASES[0]}?sslmode=require"
if VERIFY_ERR=$(PGPASSWORD="$APP_DB_PASSWORD" psql -X -q -t -A -c 'select 1' "$APP_URL" 2>&1 >/dev/null); then
    info "$APP_ROLE 로 로그인 성공 — Secret 에 넣을 값이 확정됐습니다"
else
    printf '%s\n' "$VERIFY_ERR" | head -2 | sed 's/^/      /'
    die "역할은 만들었지만 **그 비밀번호로 로그인되지 않습니다.**

    프로비저닝 자체는 관리자 권한으로 이뤄지므로 여기까지 성공해도
    애플리케이션이 붙는다는 보장이 없습니다. 그래서 확인합니다.

    흔한 원인:
      · 비밀번호에 눈에 안 보이는 문자가 섞였다(둥근따옴표 등 — 위에서 걸러내지만
        provider 콘솔에서 직접 설정했다면 이 검사에서 잡힙니다)
      · provider 가 역할 비밀번호를 따로 관리한다(콘솔에서 재설정하세요)

    ⚠️ **이 상태로 k8s/20-secret.yaml 에 값을 넣지 마세요.** 배포가
       'password authentication failed for user \"$APP_ROLE\"' 로 막히는데,
       그 메시지는 원인이 비밀번호라는 것을 알려 주지 않습니다."
fi

cat <<EOF

  ────────────────────────────────────────────────────────────────────────
   다음에 할 일

   1) k8s-overlays/external/patch-external-endpoints.yaml
        POSTGRES_HOST: "<위 ADMIN_URL 의 호스트>"
        POSTGRES_PORT: "5432"

   2) k8s/20-secret.yaml (커밋하지 않는 파일)
        LOCAL_DB_PASSWORD: "<방금 설정한 APP_DB_PASSWORD 와 같은 값>"

   3) 검증
        ops/25-provision-external-postgres.sh --check
        kubectl apply -k k8s-overlays/external

   ⚠️ 관리형 PostgreSQL 은 인터넷에 열려 있습니다. provider 콘솔에서 접근 IP 를
      OCI 인스턴스 주소로 제한하세요(Neon: IP Allow, Aiven: Allowed IP). 제한이
      불가능한 무료 티어라면 비밀번호가 유일한 방어선이라는 뜻입니다.

   ⚠️ 백업은 이제 provider 책임입니다. k8s/85-backup-cronjobs.yaml 의 pg_dump 는
      클러스터 안 PostgreSQL 을 대상으로 하므로 이 구성에서는 동작하지 않습니다.
      provider 의 PITR 보존 기간을 확인하세요(무료 티어는 대개 짧거나 없습니다).

EOF
